// ai-agents/broker/src/scopes.ts: sketch. Byte's capability pattern (src/broker.ts), as a shared service on inf.
import { createHash } from "node:crypto";
import { createAppAuth } from "@octokit/auth-app";
import type { Pool } from "pg";
import { config } from "./config.js";

export interface RunScope { // the zod schema lives in shared/src/schemas.ts
  runId: string;
  agent: string; // "nova", "cifix", ...
  repo: string; // "RhinoHealth/fcp": the one repo this run may write
  branch: string; // "nova/RH-1234": the one ref the git proxy lets it push
  readRepos: string[]; // read-only, e.g. ["RhinoHealth/rnd-kb"]
  jiraKey: string | null; slackChannel: string | null; slackThreadTs: string | null;
  expiresAt: string;
}

// Never "workflows": without it GitHub refuses any push that changes .github/workflows/.
const WRITE_PERMISSIONS = { contents: "write", pull_requests: "write", checks: "read", actions: "read" };
const auth = createAppAuth({ appId: config.githubAppId, privateKey: config.githubAppPrivateKey }); // from Vault, never in a VM

export const mintToken = async (scope: RunScope): Promise<string> => { // 1 hour, one repo; it never leaves the broker
  const { token } = await auth({
    type: "installation", installationId: config.installationId,
    repositoryNames: [scope.repo.split("/")[1] ?? ""], permissions: WRITE_PERMISSIONS,
  });
  return token;
};

// Byte compares its one capability with timingSafeEqual; here there is one per run, so we look up its sha256.
export const scopeFor = async (authorization: string | undefined, db: Pool): Promise<RunScope | null> => {
  if (!authorization?.startsWith("Bearer ")) return null; // -> 401
  const digest = createHash("sha256").update(authorization.slice("Bearer ".length)).digest("hex"); // only digests are stored
  const { rows } = await db.query<{ scope: RunScope }>("SELECT scope FROM run_scopes WHERE capability_sha256 = $1", [digest]);
  const scope = rows[0]?.scope;
  return scope && new Date(scope.expiresAt) > new Date() ? scope : null; // missing or expired -> 401
};

// ai-agents/broker/src/git-proxy.ts: sketch. The token is added here, after the checks, never in the VM.
import type { IncomingMessage, ServerResponse } from "node:http";
import { Readable } from "node:stream";

const ZERO = "0".repeat(40);
export class Refused extends Error {}

/** Refuse anything but a normal push to this run's own branch. */
export const checkReceivePack = (commands: RefUpdate[], scope: RunScope, lastPushed: string | null): void => {
  for (const cmd of commands) { // parsed from the pkt-lines before the packfile
    if (cmd.ref !== `refs/heads/${scope.branch}`) throw new Refused(`Only ${scope.branch} can be pushed from this run, not ${cmd.ref}.`);
    if (cmd.newSha === ZERO) throw new Refused("Deleting the branch is not allowed.");
    if (lastPushed && cmd.oldSha !== lastPushed) throw new Refused("The branch moved since your last push: someone else pushed. Stop and ask.");
  }
};

// POST /git/{owner}/{repo}.git/git-receive-pack
export const receivePack = async (req: IncomingMessage, res: ServerResponse, scope: RunScope, repo: string): Promise<void> => {
  if (repo !== scope.repo) return deny(res, scope, "git.push", `this run may push only to ${scope.repo}`);
  const { head, rest } = await readCommands(req); // pkt-lines, then the rest of the stream
  try {
    checkReceivePack(parsePktLines(head), scope, await pushes.last(scope.runId));
  } catch (why) {
    if (why instanceof Refused) return deny(res, scope, "git.push", why.message);
    throw why;
  }
  const token = await tokens.forScope(scope); // 1 hour, one repo
  const upstream = await fetch(`https://github.com/${scope.repo}.git/git-receive-pack`, {
    method: "POST", duplex: "half", // a streamed request body
    body: Readable.toWeb(Readable.from(chain(head, rest))),
    headers: { Authorization: basic("x-access-token", token), "Content-Type": req.headers["content-type"] ?? "" },
  });
  await pushes.record(scope, head, upstream.status); // audit + last pushed sha
  res.writeHead(upstream.status, { "Content-Type": upstream.headers.get("content-type") ?? "" });
  if (upstream.body) Readable.fromWeb(upstream.body).pipe(res);
};

// ai-agents/broker/src/people.ts: sketch. One issue, one thread, one prefix per run.
import { GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { WebClient } from "@slack/web-api";
import { z } from "zod";

const s3 = new S3Client({});
const slack = new WebClient(config.slackBotToken); // the bot token stays in the broker
const SlackPost = z.object({ text: z.string().min(1) });
const JiraComment = z.object({ issue_key: z.string(), text: z.string().min(1) }); // wire names don't change
const ArtifactRequest = z.object({ name: z.string(), write: z.boolean() });

export const peopleRoutes: Record<string, (body: unknown, scope: RunScope) => Promise<Reply>> = {
  "POST /v1/slack/post": async (body, scope) => {
    if (!scope.slackChannel || !scope.slackThreadTs) return deny(scope, "slack.post", "this run has no Slack thread");
    const text = guard(SlackPost.parse(body).text, scope); // refuses token-like strings: Byte's secret guard
    const resp = await slack.chat.postMessage({ channel: scope.slackChannel, thread_ts: scope.slackThreadTs, text, unfurl_links: false });
    return allow(scope, "slack.post", { ts: resp.ts }); // never a new top-level message, never a DM
  },

  "POST /v1/jira/comment": async (body, scope) => {
    const { issue_key, text } = JiraComment.parse(body);
    if (issue_key !== scope.jiraKey) return deny(scope, "jira.comment", `only ${scope.jiraKey} can be commented on`);
    await jira.addComment(scope.jiraKey, guard(text, scope));
    return allow(scope, "jira.comment");
  },
  "POST /v1/artifacts/url": async (body, scope) => {
    const { name, write } = ArtifactRequest.parse(body);
    const key = `runs/${scope.runId}/${safeName(name)}`; // never another run's prefix
    const params = { Bucket: RUNS_BUCKET, Key: key };
    const url = await getSignedUrl(s3, write ? new PutObjectCommand(params) : new GetObjectCommand(params), { expiresIn: 900 });
    return allow(scope, "artifacts.url", { key, url });
  },
};

