Save test/scopes.test.ts. fakeDb is a Pool with only a query method, backed by a Map, that also records every value it was asked about:

import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import type { Pool } from "pg";
import { scopeFor, type RunScope } from "../src/scopes.js";

const sha = (s: string) => createHash("sha256").update(s).digest("hex");
const CAP = "a".repeat(64); // a made-up capability
const scope = (expiresAt: string): RunScope => ({ runId: "run-1", agent: "nova", repo: "RhinoHealth/fcp",
  branch: "nova/RH-1234", readRepos: [], jiraKey: "RH-1234", slackChannel: null, slackThreadTs: null, expiresAt });

// A fake Pool: a Map from sha256(capability) to a scope, and a list of every value the "database" was asked about.
const fakeDb = (rows: Map<string, RunScope>) => {
  const seen: unknown[] = [];
  const db = { query: async (_sql: string, params: unknown[]) => {
    seen.push(...params);
    const found = rows.get(params[0] as string);
    return { rows: found ? [{ scope: found }] : [] };
  } } as unknown as Pool;
  return { db, seen };
};
const inAnHour = () => new Date(Date.now() + 3_600_000).toISOString();

test("no header, or a header that is not Bearer, gets no scope", async () => {
  const { db } = fakeDb(new Map());
  assert.equal(await scopeFor(undefined, db), null);
  assert.equal(await scopeFor(`Basic ${CAP}`, db), null);
});

test("a wrong capability gets no scope", async () => {
  const { db } = fakeDb(new Map([[sha(CAP), scope(inAnHour())]]));
  assert.equal(await scopeFor(`Bearer ${"b".repeat(64)}`, db), null);
});

test("the run's own capability gets its scope", async () => {
  const { db } = fakeDb(new Map([[sha(CAP), scope(inAnHour())]]));
  assert.equal((await scopeFor(`Bearer ${CAP}`, db))?.repo, "RhinoHealth/fcp");
});

test("an expired scope behaves like an unknown one", async () => {
  const { db } = fakeDb(new Map([[sha(CAP), scope("2026-01-01T00:00:00Z")]]));
  assert.equal(await scopeFor(`Bearer ${CAP}`, db), null);
});

test("the database only ever sees the digest, never the capability", async () => {
  const { db, seen } = fakeDb(new Map());
  await scopeFor(`Bearer ${CAP}`, db);
  assert.deepEqual(seen, [sha(CAP)]);
});
